function fresh(){return{version:1,presentationWorkloadVersion:1,lang:'en',theme:'light',shipments:structuredClone(initialShipments),deadlines:structuredClone(initialDeadlines),threads:structuredClone(initialThreads),docs:[],rules:[true,true,true],audit:[],channel:'All',order:'priority'}}
