document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay').children.length){closeOverlay();return}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-shipment],tr[data-doc]')){e.preventDefault();e.target.click()}if(e.key==='Tab'&&$('#overlay').children.length){const items=$$('#overlay button:not(:disabled),#overlay input,#overlay select,#overlay textarea,#overlay a').filter(x=>x.offsetParent!==null),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
